<?php
namespace App\Services\Import;
class CsvTemplateService {public function headers(string $m):array{return match($m){'appraisal_kras'=>['employee_email','cycle_name','kra_title','description','expected_result','actual_result','weight'],'appraisal_kpis'=>['employee_email','cycle_name','kra_title','kpi_title','measurement_method','target','actual_achievement','unit','kpi_type','weight'],'employees'=>['name','email','employee_number','department','position','supervisor_email','employment_type','work_location','start_date','status'],'mentorship'=>['mentor_email','mentee_email','session_date','duration_minutes','status','goal','goal_status','notes'],'jobs_tracking'=>['participant_email','job_id','event_type','employer','position','event_date','notes'],default=>throw new \InvalidArgumentException('Unsupported module')};}public function csv(string $m):string{$s=fopen('php://temp','r+');fputcsv($s,$this->headers($m));rewind($s);return stream_get_contents($s);}}
